function Config.HonorData.data_title_fun(slot0)
	slot1 = Config.HonorData.data_title[slot0]

	if DATA_DEBUG and slot1 == nil then
		print("(Config.HonorData.data_title[" .. slot0 .. "])not found")

		return
	end

	return slot1
end

